using System;using System.IO;using System.Linq;using System.Text;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class FinalGardenRenderAudit{
static FinalGardenRenderAudit(){EditorApplication.update+=Poll;}static void Poll(){if(!File.Exists("FinalGardenRenderAudit.request")||EditorApplication.isCompiling||EditorApplication.isPlayingOrWillChangePlaymode)return;File.Delete("FinalGardenRenderAudit.request");Run();}
static void Run(){var log=new StringBuilder();var scene=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var root=scene.GetRootGameObjects().Single(g=>g.name=="Track Roads");var all=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshRenderer>(true)).ToArray();try{
var ground=all.Single(r=>r.name=="polySurface47");var mat=ground.sharedMaterial;log.AppendLine("Shader="+mat.shader.name+" supported="+mat.shader.isSupported+" queue="+mat.renderQueue+" atlas="+mat.GetTexture("_Atlas")+" cutoff="+mat.GetFloat("_Cutoff")+" rootMatrix="+root.transform.localToWorldMatrix);var groups=root.GetComponentsInChildren<Transform>(true).Where(t=>t.name=="City Atlas Gardens and Utilities").ToArray();log.AppendLine("GROUPS="+groups.Length);
foreach(var r in all.Where(r=>r.sharedMaterial==mat).Take(8)){var m=r.GetComponent<MeshFilter>().sharedMesh;log.AppendLine("RENDER "+r.name+" enabled="+r.enabled+" layer="+r.gameObject.layer+" bounds="+r.bounds+" meshBounds="+m.bounds+" worldMatrix="+r.transform.localToWorldMatrix+" uv="+m.uv[0]+" info="+m.uv2[0]+" color="+m.colors[0]);}
var flags=all.Select(r=>r.enabled).ToArray();try{foreach(var r in all)if(r.sharedMaterial!=mat)r.enabled=false;typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,ground.bounds.center+Vector3.up*100,ground.bounds.center,"Garden-Isolated"});}finally{for(int i=0;i<all.Length;i++)if(all[i])all[i].enabled=flags[i];}
foreach(var r in all.Where(r=>r.sharedMaterial!=mat&&r.GetComponent<MeshFilter>()&&r.bounds.min.x<=ground.bounds.center.x&&r.bounds.max.x>=ground.bounds.center.x&&r.bounds.min.z<=ground.bounds.center.z&&r.bounds.max.z>=ground.bounds.center.z)){var d=typeof(FinalCitywideStops).GetMethod("Read",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{r.GetComponent<MeshFilter>()});var p=(Vector3[])d.GetType().GetField("p").GetValue(d);var ids=(int[])d.GetType().GetField("ids").GetValue(d);var args=new object[]{p,ids,ground.bounds.center,0f};if((bool)typeof(FinalPathwayRepair).GetMethod("Height",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,args))log.AppendLine("OCCLUDER "+r.name+" height="+args[3]+" shader="+r.sharedMaterial.shader.name+" bounds="+r.bounds);}var waterObjects=all.Where(r=>r.name=="Water"||r.sharedMaterials.Any(m=>m&&m.shader.name.ToLowerInvariant().Contains("water"))).ToArray();var wetFlags=waterObjects.Select(r=>r.enabled).ToArray();try{foreach(var r in waterObjects)r.enabled=false;typeof(FinalPNGCityDetails).GetMethod("Capture",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{scene,ground.bounds.center+Vector3.up*100,ground.bounds.center,"Garden-NoWater"});}finally{for(int i=0;i<waterObjects.Length;i++)waterObjects[i].enabled=wetFlags[i];}var atlas=mat.GetTexture("_Atlas");var rt=RenderTexture.GetTemporary(512,512,0);var old=RenderTexture.active;try{Graphics.Blit(atlas,rt);RenderTexture.active=rt;var tex=new Texture2D(512,512,TextureFormat.RGBA32,false);tex.ReadPixels(new Rect(0,0,512,512),0,0);tex.Apply();File.WriteAllBytes("FinalEnvironmentRoadReview/Garden-GPU-Atlas.png",tex.EncodeToPNG());log.AppendLine("GPU garden center="+tex.GetPixel((int)(.872*512),(int)(.410*512)));UnityEngine.Object.DestroyImmediate(tex);}finally{RenderTexture.active=old;RenderTexture.ReleaseTemporary(rt);}
}catch(Exception e){log.AppendLine("FAILED "+e);}File.WriteAllText("FinalEnvironmentRoadReview/GardenRenderAudit.txt",log.ToString());}}
